{"command": "cd /workspace
kubectl get pod app -o json > app-orig.json
jq 'del(.status,.metadata.uid,.metadata.resourceVersion,.metadata.creationTimestamp,.metadata.generation,.metadata.managedFields,.metadata.annotations) 
    | .spec.containers += [{
        "name":"page-writer",
        "image":"busybox:1.37.0",
        "command":["sh","-c","printf \"%s\\n\" \"<!doctype html>\" \"<html><head><title>Hello</title></head><body><h1>Hello from the page-writer sidecar</h1></body></html>\" > /srv/index.html && exec sleep 2147483647"],
        "volumeMounts":[{"name":"shared","mountPath":"/srv"}]
      }]' app-orig.json > app-new.json
jq '{name:.metadata.name, labels:.metadata.labels, containers:[.spec.containers[]|{name,image,command}], volumes:.spec.volumes}' app-new.json"}

